<div id="resource-cards" class="row row-cols-1 row-cols-md-2 row-cols-xl-3 g-4"><?php foreach ($resources as $resource): ?><div class="col"><article class="card h-100 shadow-sm resource-card"><img src="<?= htmlspecialchars($resource['screenshot_url'] ?? resource_screenshot_url($resource['url'])) ?>" class="card-img-top resource-shot" alt="Website preview" onerror="this.onerror=null;this.src='<?= $base_url ?>/images/logo.png';this.classList.add('resource-logo-fallback')"><div class="card-body d-flex flex-column"><span class="badge text-bg-primary align-self-start text-uppercase mb-2"><?= htmlspecialchars($resource['category']) ?></span><h2 class="h5"><a class="stretched-link text-decoration-none" href="<?= htmlspecialchars($resource['url']) ?>" target="_blank" rel="noopener noreferrer"><?= htmlspecialchars($resource['title']) ?></a></h2><p class="text-muted small line-clamp-3 mb-0"><?= htmlspecialchars(($resource['description'] ?? '') ?: parse_url($resource['url'], PHP_URL_HOST)) ?></p></div><div class="card-footer bg-white small text-muted d-flex justify-content-between align-items-center"><span class="text-truncate"><i class="bi bi-link-45deg"></i> <?= htmlspecialchars(parse_url($resource['url'], PHP_URL_HOST)) ?></span><a class="resource-edit-link ms-2" href="<?= $base_url ?>/resources/edit.php?url=<?= rawurlencode($resource['url']) ?>">Edit</a></div></article></div><?php endforeach; ?></div>
