<script>
(() => { const input=document.querySelector('#resource-url'), preview=document.querySelector('#resource-preview'), message=document.querySelector('#resource-preview-message'), level=document.querySelector('#resource-category'), zone=document.querySelector('#resource-zone'), lsc=document.querySelector('#resource-lsc'), regions=<?= json_encode($regions) ?>; let timer;
  const fallbackImage = '<?= $base_url ?>/images/resource-bg.png';
  document.querySelectorAll('img[src*="image.thum.io"]').forEach(image => { image.onerror = null; image.src = fallbackImage; });
  new MutationObserver(records => records.forEach(record => { const image = record.target; if (image.classList.contains('resource-logo-fallback') && image.src !== fallbackImage) image.src = fallbackImage; })).observe(document.body, {subtree:true, attributes:true, attributeFilter:['class']});
  function updateRegions() { const isNational=level.value==='national', isLsc=level.value==='lsc'; document.querySelector('.resource-region-field').classList.toggle('d-none',isNational); document.querySelector('.resource-lsc-field').classList.toggle('d-none',!isLsc); lsc.disabled=!isLsc; if (!isLsc) lsc.value=''; }
  function updateLscs() { lsc.innerHTML='<option value="">Select LSC</option>'; const entries=regions[zone.value]?.[1]||{}; Object.entries(entries).forEach(([code,name])=>lsc.add(new Option(name,code))); } level.addEventListener('change',updateRegions); zone.addEventListener('change',updateLscs); updateRegions();
  input.addEventListener('input', () => { clearTimeout(timer); preview.classList.add('d-none'); if (!input.value.trim()) return; timer=setTimeout(async () => { message.textContent='Generating website preview…'; try { const res=await fetch('<?= $base_url ?>/resources/preview.php?url='+encodeURIComponent(input.value)); const data=await res.json(); if (!data.ok) throw new Error(data.message); const p=data.preview; document.querySelector('#resource-title').value=p.title; document.querySelector('#resource-description').value=p.description; document.querySelector('#resource-details').classList.remove('d-none'); preview.innerHTML=`<div class="resource-inline-preview"><img src="${p.screenshot_url}" alt="Website screenshot" onerror="this.onerror=null;this.src='<?= $base_url ?>/images/logo.png';this.classList.add('resource-logo-fallback')"><div><strong>${escapeHtml(p.title)}</strong><p class="small text-muted mb-0">${escapeHtml(p.description || p.url)}</p></div></div>`; preview.classList.remove('d-none'); message.textContent='Review or edit the generated title and description, then post.'; } catch (err) { message.textContent=err.message || 'Preview unavailable.'; } }, 550); });
  function escapeHtml(value) { const node=document.createElement('div'); node.textContent=value; return node.innerHTML; }
  document.querySelectorAll('[data-resource-view]').forEach(button => button.addEventListener('click', () => { const cards=button.dataset.resourceView==='cards'; document.querySelector('#resource-cards')?.classList.toggle('d-none', !cards); document.querySelector('#resource-list')?.classList.toggle('d-none', cards); document.querySelectorAll('[data-resource-view]').forEach(b => b.classList.toggle('active', b===button)); }));
})();
document.querySelectorAll('#resource-list > a').forEach(link => {
  const edit = document.createElement('button');
  edit.type = 'button'; edit.className = 'btn btn-sm btn-outline-primary resource-list-edit'; edit.textContent = 'Edit';
  edit.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); window.location.href = '<?= $base_url ?>/resources/edit.php?url=' + encodeURIComponent(link.href); });
  link.appendChild(edit);
});
</script>
<?php if (!empty($recaptcha_site_key)): ?>
<script src="https://www.google.com/recaptcha/api.js?render=explicit" defer></script>
<script>
window.addEventListener('load', () => {
  const form = document.querySelector('#resource-form');
  if (!form || !window.grecaptcha) return;
  const holder = document.createElement('div'); form.appendChild(holder);
  const widget = grecaptcha.render(holder, {sitekey: '<?= htmlspecialchars($recaptcha_site_key) ?>', size: 'invisible', callback: token => { const input = document.createElement('input'); input.type = 'hidden'; input.name = 'g-recaptcha-response'; input.value = token; form.appendChild(input); form.submit(); }});
  form.addEventListener('submit', event => { if (!form.querySelector('[name="g-recaptcha-response"]')) { event.preventDefault(); grecaptcha.execute(widget); } });
});
</script>
<?php endif; ?>
